_LOCAL_METIN_INSTANCE_VIDS = set()
_LOCAL_METIN_INSTANCE_HOOKS = False

def _install_metin_instance_hooks():
    global _LOCAL_METIN_INSTANCE_HOOKS
    if _LOCAL_METIN_INSTANCE_HOOKS:
        return
    try:
        if not hasattr(chr, "CreateInstance") or not hasattr(chr, "DeleteInstance"):
            return
        if getattr(chr.CreateInstance, "__local_metin_cache_hook__", False):
            _LOCAL_METIN_INSTANCE_HOOKS = True
            return
        original_create = chr.CreateInstance
        original_delete = chr.DeleteInstance
        def _create_hook(vid, *args):
            try: _LOCAL_METIN_INSTANCE_VIDS.add(int(vid))
            except Exception: pass
            return original_create(vid, *args)
        def _delete_hook(vid, *args):
            try: _LOCAL_METIN_INSTANCE_VIDS.discard(int(vid))
            except Exception: pass
            return original_delete(vid, *args)
        _create_hook.__local_metin_cache_hook__ = True
        _delete_hook.__local_metin_cache_hook__ = True
        chr.CreateInstance = _create_hook
        chr.DeleteInstance = _delete_hook
        _LOCAL_METIN_INSTANCE_HOOKS = True
    except Exception:
        _LOCAL_METIN_INSTANCE_HOOKS = False

try:
    _install_metin_instance_hooks()
except Exception:
    pass

