    def _mark_farm_target_killed(self, now, label='Cel'):
        try:
            player.SetAttackKeyState(False)
            player.PickCloseItem()
        except Exception:
            pass
        dead_vid = int(self.__metinFarmTargetVID or 0)
        self.__metinFarmTargetVID = 0
        delay = self._farm_post_kill_delay()
        self.__metinFarmWaitUntil = now + delay
        self.__metinFarmPostKillRecheckUntil = now + delay + self._farm_post_kill_recheck()
        self.__farmStartReturnPending = bool(self.__farmSafeMode and not self.__farmCheckRespawn and self.__farmStartPosition is not None)
        self._metin_farm_log('%s zakonczony VID=%d. Zbieram drop przez 2s.%s' % (label, dead_vid, ' Powrot na start po zbieraniu.' if self.__farmStartReturnPending else ''))

    def _target_is_occupied(self, vid):
        # F8 farm must never reject a selected target because another actor is
        # believed to be attacking it. Native target/ownership formats differ
        # between client builds and caused false negatives.
        return False

    def _farm_apply_mount_policy(self, vid):
        try:
            vnum = int(chr.GetVirtualNumber(int(vid)))
            is_metin = (chr.GetInstanceType(int(vid)) == getattr(chr, 'INSTANCE_TYPE_STONE', -999) or self._is_metin_vnum(vnum))
        except Exception:
            vnum = 0
            is_metin = False
        allow_mount = bool(self._get_farm_setting('metin_from_horse') if is_metin else self._get_farm_setting('boss_from_horse'))
        self.__farmCurrentTargetMountedAllowed = allow_mount
        try:
            mounted = bool(player.IsMountingHorse())
        except Exception:
            mounted = False

        if allow_mount:
            if bool(self._get_farm_setting('auto_horse')) and not mounted:
                used = self._farm_use_horse()
                if used:
                    self.__farmHorseRideAt = app.GetTime() + 0.8
                elif self.__farmHorseRideAt > 0 and app.GetTime() >= self.__farmHorseRideAt:
                    try:
                        net.SendChatPacket('/user_horse_ride')
                    except Exception:
                        pass
                    self.__farmHorseRideAt = -9999.0
        elif mounted:
            try:
                net.SendChatPacket('/unmount')
            except Exception:
                pass
        return allow_mount

    def _farm_find_horse_item_slot(self):
        preferred = int(self._get_farm_setting('horse_item_slot'))
        vnum = int(self._get_farm_setting('horse_item_vnum'))
        if vnum <= 0:
            return -1
        try:
            if preferred >= 0 and int(player.GetItemIndex(preferred)) == vnum and int(player.GetItemCount(preferred)) > 0:
                return preferred
        except Exception:
            pass
        try:
            for slot in range(0, 5 * 45):
                if int(player.GetItemIndex(slot)) == vnum and int(player.GetItemCount(slot)) > 0:
                    return slot
        except Exception:
            pass
        return -1

    def _farm_use_horse(self):
        now = app.GetTime()
        if now - self.__farmLastHorseUse < 4.0:
            return False
        slot = self._farm_find_horse_item_slot()
        if slot < 0:
            return False
        try:
            net.SendItemUsePacket(slot)
            self.__farmLastHorseUse = now
            return True
        except Exception:
            return False

    def _farm_tick_skills(self):
        try:
            if self.__farmSkillWindow:
                self.__farmSkillWindow.Tick(bool(self.__metinFarmRunning))
        except Exception:
            pass

    def _farm_handle_death(self, now):
        try:
            max_hp = int(player.GetStatus(player.MAX_HP))
            hp = int(player.GetStatus(player.HP))
        except Exception:
            return False
        if max_hp <= 0:
            return False
        if hp <= 0:
            if not bool(self._get_farm_setting('auto_revive')):
                self._metin_farm_log('Postac zginela. Auto wstawanie OFF -> stop farmy.')
                self.StopMetinFarm()
                return True
            self.__farmRevivePending = True
            if now - self.__farmLastReviveCommand >= 3.0:
                cmd = '/restart_town' if self._get_farm_setting('revive_mode') == 'town' else '/restart_here'
                try:
                    net.SendChatPacket(cmd)
                    self.__farmLastReviveCommand = now
                    self._metin_farm_log('Smierc: wysylam %s.' % cmd)
                except Exception:
                    pass
            return True
        if self.__farmRevivePending:
            pct = (100.0 * float(hp)) / float(max_hp)
            if pct < float(self._get_farm_setting('revive_hp_percent')):
                try: player.SetAttackKeyState(False)
                except Exception: pass
                return True
            self.__farmRevivePending = False
            self.__metinFarmWaitUntil = now + 0.5
            self.__metinFarmPostKillRecheckUntil = now + 0.5
            self._metin_farm_log('Wstanie OK: HP %.0f%%, wracam do farmy.' % pct)
        return False

